KG42.register("rules-a8512fd1faf28ba48290d1de",{"id":"37-dsm_auction_incentives::v141-c-R002","paper":"37-dsm_auction_incentives","record":{"rule_id":"v141-c-R002","mechanism_id":"v141-a-M01","name":"Social-welfare clearing objective","process_stage":"clearing","market_meaning":"Declared demand information supplies the input used to select the consumption allocation that optimizes the social-welfare objective. Scope: Enhanced AGV consumption allocation under problem (18), solving social objective (15). The protocol places energy-demand submission before optimization of consumption allocations. Scope: Numbered enhanced AGV pricing procedure in Table I, using reduced scheduling problem (19). Condition: The energy provider holds each user's declared daily power-consumption amount fixed. The allocation maximizes aggregate user utility minus total electricity-provision cost over users' feasible consumption sets; each time-slot allocation must respect the user's minimum and maximum consumption limits. Scope: Social-objective consumption allocation in problems (15) and (18). With declared daily totals held fixed, the allocation minimizes total electricity-provision cost by optimizing only users' hourly consumption distribution. Scope: Reduced enhanced AGV hourly-rescheduling problem (19). Condition: The energy provider does not change any user's declared daily power-consumption amount.","independence_rationale":"Relations governed by the approved function clearing.social_welfare under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","clearing.social_welfare"],"E":[{"edge_id":"v141-c-R002-E001","source":"bidding.demand","target":"clearing.social_welfare","type":"links","constraint_ids":["v141-c-R002-C001"],"evidence_ids":["v141-b-g01-e21","v141-b-g02-e006"]},{"edge_id":"v141-c-R002-E002","source":"bidding.demand","target":"clearing.social_welfare","type":"precedes","constraint_ids":["v141-c-R002-C002"],"evidence_ids":["v141-b-g01-e29","v141-b-g02-e011"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Enhanced AGV consumption allocation under problem (18), solving social objective (15). | Numbered enhanced AGV pricing procedure in Table I, using reduced scheduling problem (19). | Reduced enhanced AGV hourly-rescheduling problem (19). | Social-objective consumption allocation in problems (15) and (18).","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e08","v141-b-g01-e21","v141-b-g01-e29","v141-b-g02-e006","v141-b-g02-e011"]},"x":[{"variable_id":"v141-c-R002-X001","symbol":"\\mathbf{x}_i","meaning":"User i's power-consumption vector over time slots, with components x_i^s; this is the consumption allocation selected in the social-welfare clearing problem.","kind":"operational","domain":"X_i = { \\mathbf{x}_i \\mid b_i^s \\le x_i^s \\le B_i^s, \\forall s \\in \\mathcal{S} } (source feasible consumption set; no separate daily-total equality is printed in (15))","unit":null,"indices":["i \\in \\mathcal{N}"],"evidence_ids":["v141-b-g01-e08","v141-b-g01-e21"]}],"theta":[{"parameter_id":"v141-c-R002-T001","symbol":"\\hat{\\theta}","meaning":"Vector of declared demand information \\hat{\\theta}=\\{\\hat{\\theta}_1,\\ldots,\\hat{\\theta}_N\\}; the AGV allocation rule is conditioned on this input. Equation (19) prints \\boldsymbol{\\theta} for the same allocation-rule argument in the supplied text.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e006","v141-b-g01-e29"]},{"parameter_id":"v141-c-R002-T002","symbol":"B_i^s","meaning":"Maximum consumption limit for user i in time slot s.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i \\in \\mathcal{N}","s \\in \\mathcal{S}"],"evidence_ids":["v141-b-g01-e08"]},{"parameter_id":"v141-c-R002-T003","symbol":"b_i^s","meaning":"Minimum consumption limit for user i in time slot s.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i \\in \\mathcal{N}","s \\in \\mathcal{S}"],"evidence_ids":["v141-b-g01-e08"]}],"phi":[{"constraint_id":"v141-c-R002-C001","kind":"mathematical","role":"core","statement":"Declared demand information supplies the input used to select the consumption allocation that optimizes the social-welfare objective. Scope: Enhanced AGV consumption allocation under problem (18), solving social objective (15).","expression":"\\mathbf{x}(\\hat{\\theta}) = \\arg\\max_{\\mathbf{x}_i \\in \\mathcal{X}_i, i\\in\\mathcal{N}} \\sum_{i\\in\\mathcal{N}} U_i\\left(\\sum_{s\\in\\mathcal{S}} x_i^s\\right) - \\sum_{s\\in\\mathcal{S}} C_s\\left(\\sum_{i\\in\\mathcal{N}} x_i^s\\right). \\tag{18}","formalization_origin":"source","template_id":null,"members":["bidding.demand","clearing.social_welfare"],"variable_refs":["v141-c-R002-X001"],"parameter_refs":["v141-c-R002-T001"],"evidence_ids":["v141-b-g01-e21","v141-b-g02-e006"]},{"constraint_id":"v141-c-R002-C002","kind":"procedural","role":"core","statement":"The protocol places energy-demand submission before optimization of consumption allocations. Scope: Numbered enhanced AGV pricing procedure in Table I, using reduced scheduling problem (19). Condition: The energy provider holds each user's declared daily power-consumption amount fixed.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","clearing.social_welfare"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e29","v141-b-g02-e011"]},{"constraint_id":"v141-c-R002-C003","kind":"mathematical","role":"core","statement":"The allocation maximizes aggregate user utility minus total electricity-provision cost over users' feasible consumption sets; each time-slot allocation must respect the user's minimum and maximum consumption limits. Scope: Social-objective consumption allocation in problems (15) and (18).","expression":"\\max_{\\mathbf{x}_i \\in X_i, i \\in \\mathcal{N}} \\sum_{i \\in \\mathcal{N}} U_i\\left(\\sum_{s \\in \\mathcal{S}} x_i^s\\right) - \\sum_{s \\in \\mathcal{S}} C_s\\left(\\sum_{i \\in \\mathcal{N}} x_i^s\\right)","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R002-X001"],"parameter_refs":["v141-c-R002-T002","v141-c-R002-T003"],"evidence_ids":["v141-b-g01-e08","v141-b-g01-e21"]},{"constraint_id":"v141-c-R002-C004","kind":"mathematical","role":"core","statement":"With declared daily totals held fixed, the allocation minimizes total electricity-provision cost by optimizing only users' hourly consumption distribution. Scope: Reduced enhanced AGV hourly-rescheduling problem (19). Condition: The energy provider does not change any user's declared daily power-consumption amount.","expression":"\\mathbf{x}(\\boldsymbol{\\theta}) = \\arg\\min_{\\mathbf{x}_i \\in X_i, i \\in \\mathcal{N}} \\sum_{s \\in \\mathcal{S}} C_s\\left(\\sum_{i \\in \\mathcal{N}} x_i^s\\right)","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R002-X001"],"parameter_refs":["v141-c-R002-T001","v141-c-R002-T002","v141-c-R002-T003"],"evidence_ids":["v141-b-g01-e29"]},{"constraint_id":"v141-c-R002-C005","kind":"mathematical","role":"supporting","statement":"User i's feasible consumption set is defined by per-slot lower and upper consumption limits.","expression":"X_i \\triangleq \\{\\mathbf{x}_i \\mid b_i^s \\le x_i^s \\le B_i^s, \\forall s \\in \\mathcal{S}\\}","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R002-X001"],"parameter_refs":["v141-c-R002-T002","v141-c-R002-T003"],"evidence_ids":["v141-b-g01-e08"]}],"pi":[{"evidence_id":"v141-b-g01-e08","location":{"location_id":"src-d83df5b2d1-p03-c1r3__v141-a-M01-clearing","page":3,"printed_page":null,"section":"II. System Model / A. DSM Scenario in the SG","anchor_text":"consumption of user in time slot . We deﬁne as the vector of energy consump- tion of user . We deﬁne","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"condition"},"source_text":"3) Consumption Boundary: We set consumption boundaries for each time slot, considering the conditions such as there are appliances that have to be always on, which causes must-run loads [20], and there exists power limitation. In time slot s, let B_i^s and b_i^s denote the maximum and minimum consumption limits for user i, respectively. We make \\mathbf{B}_i \\triangleq (B_i^1,B_i^2,\\ldots,B_i^S) and \\mathbf{b}_i \\triangleq (b_i^1,b_i^2,\\ldots,b_i^S) denote the maximum and minimum consumption limits for user i in all time slots, respectively. 4) Feasible Consumption: Let x_i^s denote the power consumption of user i in time slot s. We define \\mathbf{x}_i \\triangleq (x_i^1,x_i^2,\\ldots,x_i^S) as the vector of energy consumption of user i. We define X_i \\triangleq \\{\\mathbf{x}_i \\mid b_i^s \\le x_i^s \\le B_i^s, \\forall s \\in \\mathcal{S}\\} to be user i's feasible energy consumption set. As in [3], we also assume that user would like to shift their energy consumption in response to the price values [21]-[23]."},{"evidence_id":"v141-b-g01-e21","location":{"location_id":"src-d83df5b2d1-p05-c1r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"IV. Problem Formulation and Mechanism Solution / B. Problem Formulation","anchor_text":"MA et al.: INCENTIVE MECHANISM FOR DEMAND SIDE MANAGEMENT IN SMART GR B. Problem Formulation co tru ","equation_id":"(15)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Since we apply the utility function to represent users' benefits through electricity consumption, we can use the sum of all users' utility functions to indicate the social benefit of electricity consumption. Hence, we consider a social objective, which is to maximize the social benefit while minimizing the cost of providing that amount of electricity. This can be represented by the following problem: \\max_{\\mathbf{x}_i \\in X_i, i \\in \\mathcal{N}} \\sum_{i \\in \\mathcal{N}} U_i\\left(\\sum_{s \\in \\mathcal{S}} x_i^s\\right) - \\sum_{s \\in \\mathcal{S}} C_s\\left(\\sum_{i \\in \\mathcal{N}} x_i^s\\right), (15) where \\mathbf{x}_i is user i's power consumption vector, U_i(\\cdot) is as in (14), and C_s(\\cdot) is as in (2). The proposed energy consumption schedule is the solution of (15). Meanwhile, problem (15) is a concave maximization, which can be solved by convex programming such as the interior point method (IPM) [29]."},{"evidence_id":"v141-b-g01-e29","location":{"location_id":"src-d83df5b2d1-p05-c2r4__v141-a-M01-clearing","page":5,"printed_page":null,"section":"IV. Problem Formulation and Mechanism Solution / C. Proposed Mechanism","anchor_text":"(18) 7) We suppose that the energy provider does not change the de- clared amount of every user’s da","equation_id":"(19)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"We suppose that the energy provider does not change the declared amount of every user's daily power consumption. We only optimize users' hourly consumptive distribution. Thus, the problem in (18) can be reduced to \\mathbf{x}(\\boldsymbol{\\theta}) = \\arg\\min_{\\mathbf{x}_i \\in X_i, i \\in \\mathcal{N}} \\sum_{s \\in \\mathcal{S}} C_s\\left(\\sum_{i \\in \\mathcal{N}} x_i^s\\right). (19)"},{"evidence_id":"v141-b-g02-e006","location":{"location_id":"src-d83df5b2d1-p05-c2r3__v141-a-M01-clearing","page":5,"printed_page":null,"section":"IV. Problem Formulation and Mechanism Solution / C. Proposed Mechanism","anchor_text":". 2) Social Objective: We deﬁne the social objective in the as form of 6) where is the set of all us","equation_id":"(18)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"3) Optimal Consumption Vector: The optimal consumptive vector is set by the allocation rule \\mathbf{x}(\\hat{\\theta}) defined as follows. For a given vector of the declared demand information \\hat{\\theta} = \\{\\hat{\\theta}_1,\\ldots,\\hat{\\theta}_N\\}, the AGV mechanism chooses the consumption allocation \\mathbf{x}(\\hat{\\theta}) as the optimal solution to (15), and it calculates the optimal consumption vectors as \\[ \\mathbf{x}(\\hat{\\theta}) = \\arg\\max_{\\mathbf{x}_i \\in \\mathcal{X}_i, i\\in\\mathcal{N}} \\sum_{i\\in\\mathcal{N}} U_i\\left(\\sum_{s\\in\\mathcal{S}} x_i^s\\right) - \\sum_{s\\in\\mathcal{S}} C_s\\left(\\sum_{i\\in\\mathcal{N}} x_i^s\\right). \\tag{18} \\]"},{"evidence_id":"v141-b-g02-e011","location":{"location_id":"src-d83df5b2d1-p06-c2r1__v141-a-M01-settlement","page":6,"printed_page":null,"section":"IV. Problem Formulation and Mechanism Solution / C. Proposed Mechanism","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 5, NO. 3, MAY 2014 he TABLE I ch PRICING METHOD USING THE ENHA","equation_id":null,"figure_id":null,"table_id":"Table I","image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"TABLE I PRICING METHOD USING THE ENHANCED AGV MECHANISM 1. Registered users submit the energy demand for the next consumption cycle. * Each user selects the types of appliances and decides each type’s energy demand. The smart meter computes \\hat{x}_i and \\hat{\\psi}_i. * \\hat{\\theta}_i = \\{\\mathbf{B}_i, \\mathbf{b}_i, \\mathbf{x}_i\\}, \\psi_i and user’s consumption record will be submitted to the energy provider. 2. The energy provider optimizes users’ consumption allocations and set the payments. * Optimize users’ consumption allocations based on the submitted information by solving (19). * Compute the values of users’ payments using (20) and (23). * Announce the recommended consumption allocations and payments to users. 3. The users start the new consumption cycle, and the smart meters record users’ consumption information. Return to 1."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing","v141-a-M01-settlement"],"extras":{"decision_anchor":"clearing.social_welfare","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e006","quote":"For a given vector of the declared demand information \\hat{\\theta} = \\{\\hat{\\theta}_1,\\ldots,\\hat{\\theta}_N\\}, the AGV mechanism chooses the consumption allocation \\mathbf{x}(\\hat{\\theta}) as the optimal solution to (15)"},{"evidence_id":"v141-b-g01-e21","quote":"Hence, we consider a social objective, which is to maximize the social benefit while minimizing the cost of providing that amount of electricity."}],[{"evidence_id":"v141-b-g02-e011","quote":"1. Registered users submit the energy demand for the next consumption cycle. * Each user selects the types of appliances and decides each type’s energy demand. The smart meter computes \\hat{x}_i and \\hat{\\psi}_i. * \\hat{\\theta}_i = \\{\\mathbf{B}_i, \\mathbf{b}_i, \\mathbf{x}_i\\}, \\psi_i and user’s consumption record will be submitted to the energy provider. 2. The energy provider optimizes users’ consumption allocations and set the payments. * Optimize users’ consumption allocations based on the submitted information by solving (19)."},{"evidence_id":"v141-b-g01-e29","quote":"We suppose that the energy provider does not change the declared amount of every user's daily power consumption. We only optimize users' hourly consumptive distribution."}],[{"evidence_id":"v141-b-g01-e21","quote":"\\max_{\\mathbf{x}_i \\in X_i, i \\in \\mathcal{N}} \\sum_{i \\in \\mathcal{N}} U_i\\left(\\sum_{s \\in \\mathcal{S}} x_i^s\\right) - \\sum_{s \\in \\mathcal{S}} C_s\\left(\\sum_{i \\in \\mathcal{N}} x_i^s\\right)"},{"evidence_id":"v141-b-g01-e08","quote":"We define X_i \\triangleq \\{\\mathbf{x}_i \\mid b_i^s \\le x_i^s \\le B_i^s, \\forall s \\in \\mathcal{S}\\} to be user i's feasible energy consumption set."}],[{"evidence_id":"v141-b-g01-e29","quote":"We suppose that the energy provider does not change the declared amount of every user's daily power consumption. We only optimize users' hourly consumptive distribution. Thus, the problem in (18) can be reduced to \\mathbf{x}(\\boldsymbol{\\theta}) = \\arg\\min_{\\mathbf{x}_i \\in X_i, i \\in \\mathcal{N}} \\sum_{s \\in \\mathcal{S}} C_s\\left(\\sum_{i \\in \\mathcal{N}} x_i^s\\right). (19)"}]],"C2_formalization":{"graph_sha256":"29da5fef1e60ee77bf7c405c5bcef5e93b222c406b724d270825452f636a621a","applicability":"formalized","reason":"Formalized the social-welfare clearing objective from source equations (15), (18), and (19), plus the source feasible-set definition X_i. C002 remains procedural because it states an ordering and fixed-declaration condition rather than an equation. The printed (19) does not contain an explicit daily-total equality; that fixed-daily-amount condition is textual. The source also uses inconsistent hat/calligraphic notation for declared demand and feasible sets, so only exact local source expressions are transcribed. This provisional formalization uses unreviewed candidate evidence under the experiment policy; no independent source audit is claimed.","bindings":[{"object_id":"v141-c-R002-X001","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"The consumption vector is the operational allocation decision governed by the social-welfare clearing node."},{"object_id":"v141-c-R002-T001","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R002-E001"],"rationale":"Declared demand information is the bidding-side input linked by E001 into the social-welfare allocation rule."},{"object_id":"v141-c-R002-T002","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"The maximum per-slot consumption limit defines the feasible set in the clearing objective."},{"object_id":"v141-c-R002-T003","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"The minimum per-slot consumption limit defines the feasible set in the clearing objective."},{"object_id":"v141-c-R002-C001","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R002-E001"],"rationale":"Equation (18) defines the allocation as the argmax given declared demand information; E001 is the demand-to-clearing link."},{"object_id":"v141-c-R002-C002","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R002-E002"],"rationale":"C002 is the procedural precedence and fixed-declaration condition, represented by the precedes edge E002; it is not an equation."},{"object_id":"v141-c-R002-C003","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Equation (15) is the social-welfare maximization objective at the clearing node."},{"object_id":"v141-c-R002-C004","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Equation (19) is the reduced cost-minimization allocation subproblem at the clearing node under fixed declared daily amounts."},{"object_id":"v141-c-R002-C005","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"The feasible-set definition supplies the per-slot bounds used by the clearing allocation expressions."}],"revision_requests":[]}},"quarantined_references":[]}});
